import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"收发与整理邮件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mail.md","filePath":"guide/mail.md","lastUpdated":1788621106000}`),a={name:`guide/mail.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="收发与整理邮件" tabindex="-1">收发与整理邮件 <a class="header-anchor" href="#收发与整理邮件" aria-label="Permalink to “收发与整理邮件”">​</a></h1><h2 id="邮箱与文件夹" tabindex="-1">邮箱与文件夹 <a class="header-anchor" href="#邮箱与文件夹" aria-label="Permalink to “邮箱与文件夹”">​</a></h2><p>登录后默认打开第一个可用邮箱。邮箱选择器支持单邮箱和“全部邮箱”视图；全部邮箱只汇总当前账号拥有或获准访问的邮箱，不会跨用户泄露邮件。</p><p>系统文件夹包括收件箱、星标、草稿、已发送、归档、稍后提醒、已删除和垃圾邮件。用户还可以建立自定义文件夹和标签。</p><h2 id="邮件列表" tabindex="-1">邮件列表 <a class="header-anchor" href="#邮件列表" aria-label="Permalink to “邮件列表”">​</a></h2><p>邮件列表支持分页、未读状态、星标、选择多封邮件和批量操作。常用批量操作包括标记已读、归档、移动、删除和彻底删除。搜索会在当前用户有权访问的邮件范围内执行。</p><h2 id="阅读与会话" tabindex="-1">阅读与会话 <a class="header-anchor" href="#阅读与会话" aria-label="Permalink to “阅读与会话”">​</a></h2><p>邮件详情展示发件人、收件人、抄送、时间、正文和附件，并可查看同一会话的相关邮件。正文会经过安全处理，避免邮件中的脚本直接在应用里执行。</p><p>“查看原始邮件”用于检查完整邮件头、投递路径和 MIME 内容。该能力只对邮箱所有者或获得相应权限的协作者开放。</p><h2 id="spf、dkim-与-dmarc-提示" tabindex="-1">SPF、DKIM 与 DMARC 提示 <a class="header-anchor" href="#spf、dkim-与-dmarc-提示" aria-label="Permalink to “SPF、DKIM 与 DMARC 提示”">​</a></h2><p>详情页会展示入站认证结果：</p><ul><li><strong>SPF</strong>：发件服务器是否获得域名授权。</li><li><strong>DKIM</strong>：邮件签名是否完整且与发件域名匹配。</li><li><strong>DMARC</strong>：发件域名的整体认证策略是否通过。</li></ul><p>单项失败并不能独立证明邮件恶意，但遇到身份异常、陌生链接或可执行附件时应提高警惕。</p><h2 id="写信与草稿" tabindex="-1">写信与草稿 <a class="header-anchor" href="#写信与草稿" aria-label="Permalink to “写信与草稿”">​</a></h2><p>写信窗口支持发件邮箱、收件人、抄送、密送、主题、富文本或 Markdown 正文、附件、签名和图片上传。草稿可以反复保存，发送成功后会进入已发送邮件。</p><p>系统发送前会检查发件邮箱归属、发信权限、每日额度、收件人风险、抑制名单以及可用发信通道。错误提示应保留完整文字和发生时间，便于管理员排查。</p><h2 id="附件、导入与导出" tabindex="-1">附件、导入与导出 <a class="header-anchor" href="#附件、导入与导出" aria-label="Permalink to “附件、导入与导出”">​</a></h2><p>附件通过受控下载接口提供，缩略图同样需要权限校验。邮箱支持邮件导入与导出；处理大量数据前应确认剩余存储配额，并避免重复提交。</p><h2 id="垃圾邮件与隔离区" tabindex="-1">垃圾邮件与隔离区 <a class="header-anchor" href="#垃圾邮件与隔离区" aria-label="Permalink to “垃圾邮件与隔离区”">​</a></h2><p>rspamd 会结合内容、来源、认证结果和信誉判断风险。高风险邮件可能进入垃圾邮件或隔离区。隔离区中可查看、申诉、释放或删除邮件；释放前应确认发件人和附件安全。</p><h2 id="删除与清理" tabindex="-1">删除与清理 <a class="header-anchor" href="#删除与清理" aria-label="Permalink to “删除与清理”">​</a></h2><p>普通删除通常先进入已删除区域。清理中心支持预约删除、取消清理和永久保留；“彻底删除”或清空邮箱无法通过网页恢复，操作前应先确认选中的邮箱和邮件范围。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};